CREATE TABLE public.studio_character_sheets (id uuid PRIMARY KEY, user_id uuid NOT NULL, project_id uuid NOT NULL REFERENCES public.video_inspiration_projects(id), brief jsonb NOT NULL, instructions text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'claimed' CHECK(status IN ('claimed','in_progress','completed','failed','approved')), billed integer NOT NULL DEFAULT 0, result_path text, failure_reason text, reference_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.studio_character_sheets TO authenticated; GRANT ALL ON public.studio_character_sheets TO service_role; ALTER TABLE public.studio_character_sheets ENABLE ROW LEVEL SECURITY; CREATE POLICY character_sheet_owner_read ON public.studio_character_sheets FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE UNIQUE INDEX character_sheet_one_running ON public.studio_character_sheets(project_id) WHERE status IN ('claimed','in_progress'); ALTER TABLE public.reference_assets ADD COLUMN IF NOT EXISTS character_sheet_id uuid REFERENCES public.studio_character_sheets(id);